import type { AgentConversation, AgentTokenUsage, ProjectSnapshot } from '../../data/data_types'
import { sumAgentTokenUsage } from '../../../../shared/agent_usage_math.mjs'
import type { AgentTokenUsageSummary } from '../../../../shared/agent_token_usage_summary.mjs'

export { sumAgentTokenUsage }

export interface AgentUsageVersion {
    name: string
    usage: AgentTokenUsage
}

export interface AgentFileChangeUsage {
    deletions: number
    insertions: number
}

export interface ProjectAgentUsage {
    archived: AgentUsageVersion
    current: AgentUsageVersion
    project: AgentTokenUsage
    releases: AgentUsageVersion[]
}

export function cardAgentTokenUsage(source: AgentConversation[] | ProjectSnapshot['activeCards'][number]): AgentTokenUsage {
    const conversations = Array.isArray(source) ? source : source.agentConversations

    return sumAgentTokenUsage(conversations.map(({ usage }) => usage))
}

/** Aggregate loaded conversations belonging to one action on one card. */
export function actionCardAgentTokenUsage(conversations: AgentConversation[], actionId: string, cardInternalId: string): AgentTokenUsage {
    const matchingUsage = conversations
        .filter((conversation) => conversation.actionId === actionId && conversation.cardInternalId === cardInternalId)
        .map(({ usage }) => usage)

    return sumAgentTokenUsage(matchingUsage)
}

/** Sum completed provider patches in one canonical conversation. */
export function conversationFileChangeUsage(conversation: AgentConversation | null): AgentFileChangeUsage | null {
    if (!conversation) return null
    let countedEvents = 0
    let deletions = 0
    let insertions = 0
    for (const entry of conversation.entries) {
        if (entry.kind !== 'event' || entry.type !== 'fileChange' || entry.status !== 'completed') continue
        const { deletions: eventDeletions, insertions: eventInsertions } = entry
        if (typeof eventDeletions !== 'number' || !Number.isSafeInteger(eventDeletions) || eventDeletions < 0) continue
        if (typeof eventInsertions !== 'number' || !Number.isSafeInteger(eventInsertions) || eventInsertions < 0) continue

        countedEvents += 1
        deletions += eventDeletions
        insertions += eventInsertions
    }

    return countedEvents > 0 ? { deletions, insertions } : null
}

function isInsideFolder(cardPath: string, folder: string) {
    const normalizedFolder = folder.replace(/\\/gu, '/').replace(/^\/+|\/+$/gu, '')
    const normalizedCardPath = cardPath.replace(/\\/gu, '/')

    return normalizedCardPath.startsWith(`${normalizedFolder}/`)
}

/** Use persisted project/release totals while deriving current and archived detail from loaded activity. */
export function projectAgentTokenUsage(
    snapshot: ProjectSnapshot | null,
    archivedFolder: string,
    summary: AgentTokenUsageSummary,
): ProjectAgentUsage {
    const activeCards = snapshot?.activeCards ?? []
    const backgroundCards = snapshot?.backgroundCards ?? []
    const currentUsage = sumAgentTokenUsage(activeCards.map(({ agentConversations }) => cardAgentTokenUsage(agentConversations)))
    const archivedUsage = sumAgentTokenUsage(
        backgroundCards
            .filter((card) => isInsideFolder(card.path, archivedFolder))
            .map(({ agentConversations }) => cardAgentTokenUsage(agentConversations)),
    )
    const releases = Object.entries(summary.releases)
        .map(([name, usage]) => ({ name, usage }))
        .sort((left, right) => left.name.localeCompare(right.name))

    return {
        archived: { name: 'Archived', usage: archivedUsage },
        current: { name: 'Current', usage: currentUsage },
        project: summary.projectUsage,
        releases,
    }
}

function usageNumber(value) {
    return typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : 0
}

function requireUsageNumber(value, fieldName) {
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
        throw new Error(`Invalid provider token usage ${fieldName}`)
    }

    return value
}

/**
 * Coerce a provider usage record into the shape `sumAgentTokenUsage` relies on: five finite
 * non-negative counters plus an optional `costUsd`. `totalTokens` is always recomputed from the
 * buckets rather than trusted, so provider totals can never disagree with their own parts.
 */
export function normalizeAgentTokenUsage(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null

    const usage = {
        cachedInputTokens: usageNumber(value.cachedInputTokens),
        inputTokens: usageNumber(value.inputTokens),
        outputTokens: usageNumber(value.outputTokens),
        reasoningTokens: usageNumber(value.reasoningTokens),
    }
    if (value.legacyTotalTokens !== undefined) usage.legacyTotalTokens = usageNumber(value.legacyTotalTokens)
    usage.totalTokens = (usage.legacyTotalTokens ?? 0)
        + usage.inputTokens
        + usage.cachedInputTokens
        + usage.outputTokens
        + usage.reasoningTokens
    if (typeof value.costUsd === 'number' && Number.isFinite(value.costUsd) && value.costUsd >= 0) usage.costUsd = value.costUsd

    return usage
}

/** Validate disjoint usage buckets emitted for one newly completed provider turn. */
export function validateAgentTokenUsage(value, providerTotalTokens) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        throw new Error('Invalid provider token usage')
    }
    const usage = {
        cachedInputTokens: requireUsageNumber(value.cachedInputTokens, 'cachedInputTokens'),
        inputTokens: requireUsageNumber(value.inputTokens, 'inputTokens'),
        outputTokens: requireUsageNumber(value.outputTokens, 'outputTokens'),
        reasoningTokens: requireUsageNumber(value.reasoningTokens, 'reasoningTokens'),
    }
    usage.totalTokens = usage.inputTokens + usage.cachedInputTokens + usage.outputTokens + usage.reasoningTokens
    if (providerTotalTokens !== undefined) {
        const totalTokens = requireUsageNumber(providerTotalTokens, 'totalTokens')
        if (usage.totalTokens !== totalTokens) {
            throw new Error(`Inconsistent provider token usage total: expected ${totalTokens}, received ${usage.totalTokens}`)
        }
    }
    if (value.costUsd !== undefined) usage.costUsd = requireUsageNumber(value.costUsd, 'costUsd')

    return usage
}

/** Sum normalized agent token usage records, skipping absent entries; costUsd only appears when a provider reported one. */
export function sumAgentTokenUsage(usages) {
    const total = { cachedInputTokens: 0, inputTokens: 0, outputTokens: 0, reasoningTokens: 0, totalTokens: 0 }
    let hasReportedCost = false
    let hasLegacyTotal = false

    for (const usage of usages) {
        if (!usage) continue

        total.cachedInputTokens += usage.cachedInputTokens
        total.inputTokens += usage.inputTokens
        total.outputTokens += usage.outputTokens
        total.reasoningTokens += usage.reasoningTokens
        total.totalTokens += usage.totalTokens
        if (usage.legacyTotalTokens !== undefined) {
            total.legacyTotalTokens = (total.legacyTotalTokens ?? 0) + usage.legacyTotalTokens
            hasLegacyTotal = true
        }
        if (usage.costUsd !== undefined) {
            total.costUsd = (total.costUsd ?? 0) + usage.costUsd
            hasReportedCost = true
        }
    }
    if (!hasReportedCost) delete total.costUsd
    if (!hasLegacyTotal) delete total.legacyTotalTokens

    return total
}
